#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# Provisions the Azure side of ticket 14, once, by hand (ADR-0010): the
# resource group, the Log Analytics workspace, the Container Apps environment
# and app, the first image on GHCR made public, the Entra app registration
# GitHub Actions signs in as through OIDC, the API key, the repository
# secrets and variables the deploy job reads, and a cost budget, leaving the
# app's ingress closed. Every Azure call is the Azure CLI's,
# so the commands below are the record of what exists. Re-runnable: values
# are remembered in .env.azure (gitignored, no secret in it); the
# environment, the app, the Entra app and its role are skipped when they
# exist, the credential is skipped when its subject is already right (and
# updated when it is not), and the rest is safe to repeat (az create on an
# existing group or workspace changes nothing; stage 5 pushes :bootstrap
# again).
#
#   bash scripts/provision-azure.sh        # from the repo root, in Git Bash
#
# Needs the Azure CLI (winget install -e --id Microsoft.AzureCLI), Docker
# Desktop running, openssl (Git Bash has it), and gh signed in. The Anthropic
# key is typed hidden, goes into a Container Apps secret through a private
# temp file, and is never written to .env.azure, a command line or GitHub.
# The API key /reformat requires is generated here, stored as a Container
# Apps secret and as the GitHub secret the deploy's smoke test sends, and
# never printed or written to .env.azure. The app's ingress is left closed:
# it is opened for demos only (scripts/demo.sh up).

cd "$(dirname "$0")/.."
ENV_FILE=.env.azure
# Git Bash would otherwise rewrite Azure resource ids (/subscriptions/...)
# into Windows paths.
export MSYS_NO_PATHCONV=1

# az on Windows ends its output lines with CR; strip it from captured values.
azq() { az "$@" | tr -d '\r'; }

# wait_app_ready: every change to the app (secret set, update) starts an
# operation, and the next az call on the app fails with ContainerAppLockConflict
# until it ends. Poll provisioningState until it is Succeeded, for at most
# 5 minutes.
wait_app_ready() {
  local state=""
  for _ in $(seq 60); do
    state=$(azq containerapp show --name "$AZURE_CONTAINER_APP" --resource-group "$AZURE_RESOURCE_GROUP" \
      --query properties.provisioningState -o tsv)
    [[ "$state" == Succeeded ]] && return 0
    [[ "$state" == Failed ]] && break
    sleep 5
  done
  warn "$AZURE_CONTAINER_APP did not reach Succeeded (last state: ${state:-unknown}); see the portal"
  exit 1
}

# env_var_is NAME EXPECTED: whether the app's container already has env var
# NAME as EXPECTED, a literal value or secretref:<secret>. Read-only, so a
# re-run that changes nothing creates no revision.
env_var_is() {
  local name="$1" want="$2" got
  if [[ "$want" == secretref:* ]]; then
    got=$(azq containerapp show --name "$AZURE_CONTAINER_APP" --resource-group "$AZURE_RESOURCE_GROUP" \
      --query "properties.template.containers[0].env[?name=='$name'].secretRef | [0]" -o tsv)
    got="secretref:$got"
  else
    got=$(azq containerapp show --name "$AZURE_CONTAINER_APP" --resource-group "$AZURE_RESOURCE_GROUP" \
      --query "properties.template.containers[0].env[?name=='$name'].value | [0]" -o tsv)
  fi
  [[ "$got" == "$want" ]]
}

# az is a Windows program under Git Bash, and MSYS_NO_PATHCONV stops a /tmp
# path being translated for it, so temp files are handed over in Windows form.
winpath() {
  if command -v cygpath >/dev/null 2>&1; then cygpath -m "$1"; else printf '%s' "$1"; fi
}

# ask_default KEY "Prompt" DEFAULT: ask (Enter keeps a remembered value),
# fall back to DEFAULT when nothing is remembered, and remember the result.
ask_default() {
  local key="$1" prompt="$2" default="$3"
  ask "$key" "$prompt [$default]"
  [[ -n "${!key}" ]] || printf -v "$key" '%s' "$default"
  write_env "$key" "${!key}"
}

need() {
  command -v "$1" >/dev/null 2>&1 || { warn "$1 not found: $2"; exit 1; }
}

TOTAL_STAGES=14

banner "cv-reformatter: Azure Container Apps, deployed through OIDC"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Tools and Azure sign-in"
need az "install it with: winget install -e --id Microsoft.AzureCLI (then reopen Git Bash)"
need docker "install Docker Desktop"
need gh "install the GitHub CLI"
need openssl "it comes with Git for Windows; run the wizard in Git Bash"
docker info >/dev/null 2>&1 || { warn "Docker is not running: start Docker Desktop"; exit 1; }
gh auth status >/dev/null 2>&1 || { warn "gh is not signed in: run gh auth login"; exit 1; }
say "az, docker and gh are present."
if az account show >/dev/null 2>&1; then
  note "Already signed in to Azure as $(azq account show --query user.name -o tsv)."
else
  step "A browser opens for the Azure sign-in; pick your personal account."
  note "(If a Windows sign-in popup appears instead and fails silently, stop and run"
  note " az config set core.enable_broker_on_windows=false, then re-run the wizard.)"
  pause "Press Enter to run az login"
  az login --output none
fi
az account list --query "[].{name:name, id:id, default:isDefault}" --output table
ask_default AZURE_SUBSCRIPTION_ID "Subscription to use (name or id)" "$(azq account show --query id -o tsv)"
az account set --subscription "$AZURE_SUBSCRIPTION_ID"
# A name was accepted above; from here on (and in GitHub) it is the id.
AZURE_SUBSCRIPTION_ID=$(azq account show --query id -o tsv)
write_env AZURE_SUBSCRIPTION_ID "$AZURE_SUBSCRIPTION_ID"
note "Using $(azq account show --query name -o tsv) ($AZURE_SUBSCRIPTION_ID)."
AZURE_TENANT_ID=$(azq account show --query tenantId -o tsv)
write_env AZURE_TENANT_ID "$AZURE_TENANT_ID"
say "Registering the resource providers Container Apps needs (a minute or two the first time)."
az provider register --namespace Microsoft.App --wait
az provider register --namespace Microsoft.OperationalInsights --wait
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Names and region"
say "Enter keeps the default shown in brackets."
ask_default AZURE_LOCATION "Region" northeurope
ask_default AZURE_RESOURCE_GROUP "Resource group" cvr-rg
ask_default LOG_WORKSPACE "Log Analytics workspace" cvr-log
ask_default CONTAINERAPPS_ENV "Container Apps environment" cvr-cae
ask_default AZURE_CONTAINER_APP "Container app (its name is in the public URL)" cvr-ca
ask_default ENTRA_APP "Entra app registration GitHub Actions signs in as" cvr-github-deploy
ask_default GITHUB_REPO "GitHub repository (owner/name)" "$(gh repo view --json nameWithOwner -q .nameWithOwner)"
IMAGE="ghcr.io/${GITHUB_REPO,,}"
write_env IMAGE "$IMAGE"
# The subject GitHub puts in the OIDC token is not always the repo name: a
# repository on the immutable format (this one) carries the owner and repo ids,
# so the trust follows the repository itself and not whoever holds the name
# later. Ask GitHub for the prefix instead of guessing. Always recomputed, so
# a subject remembered in .env.azure from an earlier run never wins.
sub_prefix=$(gh api "repos/$GITHUB_REPO/actions/oidc/customization/sub" --jq '.sub_claim_prefix // empty' 2>/dev/null | tr -d '\r' || true)
if [[ -z "$sub_prefix" ]]; then
  warn "GitHub gave no OIDC subject prefix for $GITHUB_REPO; assuming the legacy repo:$GITHUB_REPO."
  note "If the deploy job later fails with AADSTS700213, compare its subject with the credential."
  sub_prefix="repo:$GITHUB_REPO"
fi
FED_SUBJECT="$sub_prefix:ref:refs/heads/main"
write_env FED_SUBJECT "$FED_SUBJECT"
note "Image: $IMAGE    OIDC subject: $FED_SUBJECT"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Resource group and Log Analytics workspace"
say "Creates (or confirms) $AZURE_RESOURCE_GROUP and $LOG_WORKSPACE in $AZURE_LOCATION."
note "Log Analytics bills ingestion past its free allowance; this app logs a few KB a request."
confirm "Create them?" || { warn "stopped before creating anything"; exit 1; }
az group create --name "$AZURE_RESOURCE_GROUP" --location "$AZURE_LOCATION" --output none
az monitor log-analytics workspace create --resource-group "$AZURE_RESOURCE_GROUP" \
  --workspace-name "$LOG_WORKSPACE" --location "$AZURE_LOCATION" --retention-time 30 --output none
LOG_WORKSPACE_ID=$(azq monitor log-analytics workspace show --resource-group "$AZURE_RESOURCE_GROUP" \
  --workspace-name "$LOG_WORKSPACE" --query customerId -o tsv)
write_env LOG_WORKSPACE_ID "$LOG_WORKSPACE_ID"
say "Done. Workspace (customer) id: $LOG_WORKSPACE_ID"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Container Apps environment"
if az containerapp env show --name "$CONTAINERAPPS_ENV" --resource-group "$AZURE_RESOURCE_GROUP" >/dev/null 2>&1; then
  say "$CONTAINERAPPS_ENV already exists; skipping."
else
  say "Creates $CONTAINERAPPS_ENV: consumption only (no workload profiles), logs to $LOG_WORKSPACE."
  note "Takes a few minutes."
  confirm "Create it?" || { warn "stopped"; exit 1; }
  log_key=$(azq monitor log-analytics workspace get-shared-keys --resource-group "$AZURE_RESOURCE_GROUP" \
    --workspace-name "$LOG_WORKSPACE" --query primarySharedKey -o tsv)
  az containerapp env create --name "$CONTAINERAPPS_ENV" --resource-group "$AZURE_RESOURCE_GROUP" \
    --location "$AZURE_LOCATION" --enable-workload-profiles false \
    --logs-destination log-analytics --logs-workspace-id "$LOG_WORKSPACE_ID" \
    --logs-workspace-key "$log_key" --output none
  unset log_key
  say "Done."
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "First image on GHCR"
say "Container Apps pulls with no registry secret, so the package must exist and"
say "be public before the app is created. This builds the image here and pushes"
say "$IMAGE:bootstrap; the deploy job replaces it on the first merge to main."
step "gh needs the write:packages scope: a browser may open for a one-time code."
pause "Press Enter to refresh gh's scopes"
gh auth refresh --hostname github.com --scopes write:packages
gh auth token | docker login ghcr.io --username "$(gh api user --jq .login)" --password-stdin
docker build --label "org.opencontainers.image.source=https://github.com/$GITHUB_REPO" \
  --tag "$IMAGE:bootstrap" .
docker push "$IMAGE:bootstrap"
docker logout ghcr.io
say "Pushed, and docker is logged out of ghcr.io again."
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "GHCR package: public, and writable by the repo's Actions"
OWNER=${GITHUB_REPO%%/*}
PACKAGE=${GITHUB_REPO##*/}
open_url "https://github.com/users/$OWNER/packages/container/$PACKAGE/settings"
step "Danger Zone → Change visibility → Public → type '$PACKAGE' → confirm."
step "Manage Actions access → Add repository → $PACKAGE → role Write."
note "  (If $PACKAGE is already listed there, make sure its role is Write.)"
warn "Public means anyone can pull the image; ticket 12's checks keep secrets out of it."
pause "Press Enter once both are saved"
say "Checking an anonymous pull, and repeating ticket 12's inspection on the pushed image."
docker image rm "$IMAGE:bootstrap" >/dev/null 2>&1 || true
IMAGE="$IMAGE:bootstrap" PULL=1 sh scripts/check-image.sh
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "The container app"
if az containerapp show --name "$AZURE_CONTAINER_APP" --resource-group "$AZURE_RESOURCE_GROUP" >/dev/null 2>&1; then
  say "$AZURE_CONTAINER_APP already exists; skipping. To rotate its key, see"
  note "  docs/development.md, Deployment (read hidden, never typed into the history)."
else
  say "Creates $AZURE_CONTAINER_APP on $IMAGE:bootstrap: external ingress on 8000,"
  say "0 to 1 replicas, liveness and readiness probes on /health, 0.5 vCPU and 1 GiB,"
  say "and the Anthropic key as the Container Apps secret anthropic-api-key, which"
  say "the container reads as ANTHROPIC_API_KEY."
  open_url "https://console.anthropic.com/settings/keys"
  step "Create a key for this deployment (e.g. cvr-container-app) and copy it."
  ask_secret ANTHROPIC_API_KEY "Paste the key (hidden):"
  [[ -n "$ANTHROPIC_API_KEY" ]] || { warn "no key entered"; exit 1; }
  confirm "Create the app?" || { warn "stopped"; exit 1; }
  # The app is PUT to the ARM API as JSON with az rest, not through
  # `az containerapp create --yaml`: the CLI re-serialises a YAML spec through
  # its SDK model and sends every unset field as null, which ARM rejects ("The
  # JSON value could not be converted to System.Boolean"). The flag-based
  # create would put the key on the command line. Here the spec holds the
  # key, so the key never appears on a command line; the file is deleted as
  # soon as az has read it, and by the trap if the wizard is interrupted.
  # (chmod is best effort: on NTFS the user's temp directory is what keeps it
  # private.)
  env_id=$(azq containerapp env show --name "$CONTAINERAPPS_ENV" --resource-group "$AZURE_RESOURCE_GROUP" --query id -o tsv)
  app_uri="https://management.azure.com/subscriptions/$AZURE_SUBSCRIPTION_ID/resourceGroups/$AZURE_RESOURCE_GROUP/providers/Microsoft.App/containerApps/$AZURE_CONTAINER_APP?api-version=2024-03-01"
  spec=$(mktemp)
  trap 'rm -f "$spec"' EXIT
  chmod 600 "$spec"
  cat > "$spec" <<JSON
{
  "location": "$AZURE_LOCATION",
  "properties": {
    "environmentId": "$env_id",
    "configuration": {
      "activeRevisionsMode": "Single",
      "ingress": {"external": true, "targetPort": 8000, "transport": "auto"},
      "secrets": [{"name": "anthropic-api-key", "value": "$ANTHROPIC_API_KEY"}]
    },
    "template": {
      "containers": [{
        "name": "cvr",
        "image": "$IMAGE:bootstrap",
        "resources": {"cpu": 0.5, "memory": "1Gi"},
        "env": [{"name": "ANTHROPIC_API_KEY", "secretRef": "anthropic-api-key"}],
        "probes": [
          {"type": "Liveness", "httpGet": {"path": "/health", "port": 8000},
           "initialDelaySeconds": 5, "periodSeconds": 30},
          {"type": "Readiness", "httpGet": {"path": "/health", "port": 8000},
           "initialDelaySeconds": 5, "periodSeconds": 10}
        ]
      }],
      "scale": {"minReplicas": 0, "maxReplicas": 1}
    }
  }
}
JSON
  created=0
  # A body read from a file gets no Content-Type of its own; ARM requires one.
  az rest --method PUT --uri "$app_uri" --headers "Content-Type=application/json" \
    --body "@$(winpath "$spec")" --output none && created=1
  rm -f "$spec"
  trap - EXIT
  unset ANTHROPIC_API_KEY
  [[ "$created" == 1 ]] || { warn "create failed; the spec file is deleted"; exit 1; }
  say "Accepted; the spec file that held the key is deleted. Waiting for provisioning."
  for _ in $(seq 60); do
    state=$(azq containerapp show --name "$AZURE_CONTAINER_APP" --resource-group "$AZURE_RESOURCE_GROUP" \
      --query properties.provisioningState -o tsv)
    [[ "$state" == Succeeded || "$state" == Failed ]] && break
    sleep 5
  done
  [[ "$state" == Succeeded ]] || { warn "provisioning ended as '$state'; see the app in the portal"; exit 1; }
  say "Done: $AZURE_CONTAINER_APP is provisioned."
fi
# The key /reformat requires (X-API-Key). Generated once and kept in the
# Container Apps secret cvr-api-key; a re-run reads it back, so the app and
# GitHub always hold the same value. It is on az's command line for the one
# call that sets it: generated here, never typed, and rotatable by deleting
# the secret and re-running this stage.
say "The API key /reformat requires: a Container Apps secret cvr-api-key, read by"
say "the container as CVR_API_KEY, and the GitHub secret CVR_API_KEY for the"
say "deploy's smoke test. Never printed. For a demo, read it with:"
note "  az containerapp secret show --name $AZURE_CONTAINER_APP --resource-group $AZURE_RESOURCE_GROUP --secret-name cvr-api-key --query value -o tsv"
has_key=$(azq containerapp secret list --name "$AZURE_CONTAINER_APP" --resource-group "$AZURE_RESOURCE_GROUP" \
  --query "length([?name=='cvr-api-key'])" -o tsv)
if [[ "$has_key" == 0 ]]; then
  CVR_API_KEY=$(openssl rand -hex 32)
  az containerapp secret set --name "$AZURE_CONTAINER_APP" --resource-group "$AZURE_RESOURCE_GROUP" \
    --secrets "cvr-api-key=$CVR_API_KEY" --output none
  wait_app_ready
  say "Generated a new key into cvr-api-key."
else
  CVR_API_KEY=$(azq containerapp secret show --name "$AZURE_CONTAINER_APP" --resource-group "$AZURE_RESOURCE_GROUP" \
    --secret-name cvr-api-key --query value -o tsv)
  say "cvr-api-key already exists; keeping it."
fi
# For the smoke test in stage 8, which unsets it again.
export CVR_API_KEY
# An update makes a new revision, so only when the env is not already as wanted.
if ! env_var_is CVR_API_KEY secretref:cvr-api-key; then
  az containerapp update --name "$AZURE_CONTAINER_APP" --resource-group "$AZURE_RESOURCE_GROUP" \
    --set-env-vars CVR_API_KEY=secretref:cvr-api-key --output none
  wait_app_ready
fi
set_secret CVR_API_KEY "$CVR_API_KEY"

# Langfuse (Phase 2, ticket 08): every Run the app handles is traced as a
# structure trace (ids, counts, timings, tokens, cost; never CV text). The two
# keys are Container Apps secrets, read by the container as LANGFUSE_PUBLIC_KEY
# and LANGFUSE_SECRET_KEY, and GitHub secrets of the same names for the eval
# job. Idempotent like cvr-api-key: a re-run keeps the secrets it finds and
# reads them back for GitHub. Like cvr-api-key, they are on az's command line
# for the one call that sets them. Without them the app runs untraced.
say "Langfuse tracing: Container Apps secrets langfuse-public-key and"
say "langfuse-secret-key (read as LANGFUSE_PUBLIC_KEY and LANGFUSE_SECRET_KEY),"
say "LANGFUSE_BASE_URL, and CVR_TRACE_ENV=prod, which tags the app's traces."
say "Create a key pair in your private Langfuse project (Settings > API Keys)."
has_langfuse=$(azq containerapp secret list --name "$AZURE_CONTAINER_APP" --resource-group "$AZURE_RESOURCE_GROUP" \
  --query "length([?name=='langfuse-public-key' || name=='langfuse-secret-key'])" -o tsv)
if [[ "$has_langfuse" == 2 ]]; then
  say "langfuse-public-key and langfuse-secret-key already exist; keeping them."
  LANGFUSE_PUBLIC_KEY=$(azq containerapp secret show --name "$AZURE_CONTAINER_APP" --resource-group "$AZURE_RESOURCE_GROUP" \
    --secret-name langfuse-public-key --query value -o tsv)
  LANGFUSE_SECRET_KEY=$(azq containerapp secret show --name "$AZURE_CONTAINER_APP" --resource-group "$AZURE_RESOURCE_GROUP" \
    --secret-name langfuse-secret-key --query value -o tsv)
else
  open_url "https://cloud.langfuse.com"
  ask_secret LANGFUSE_PUBLIC_KEY "Public key, pk-lf-... (hidden; Enter skips tracing):"
  if [[ -n "$LANGFUSE_PUBLIC_KEY" ]]; then
    ask_secret LANGFUSE_SECRET_KEY "Secret key, sk-lf-... (hidden):"
    if [[ -z "$LANGFUSE_SECRET_KEY" ]]; then
      warn "no secret key entered; skipping tracing"
      LANGFUSE_PUBLIC_KEY=""
    else
      az containerapp secret set --name "$AZURE_CONTAINER_APP" --resource-group "$AZURE_RESOURCE_GROUP" \
        --secrets "langfuse-public-key=$LANGFUSE_PUBLIC_KEY" "langfuse-secret-key=$LANGFUSE_SECRET_KEY" --output none
      wait_app_ready
      say "Stored langfuse-public-key and langfuse-secret-key."
    fi
  fi
fi
if [[ -n "$LANGFUSE_PUBLIC_KEY" && -n "$LANGFUSE_SECRET_KEY" ]]; then
  ask_default LANGFUSE_BASE_URL "Langfuse base URL (EU cloud)" "https://cloud.langfuse.com"
  if ! { env_var_is LANGFUSE_PUBLIC_KEY secretref:langfuse-public-key &&
    env_var_is LANGFUSE_SECRET_KEY secretref:langfuse-secret-key &&
    env_var_is LANGFUSE_BASE_URL "$LANGFUSE_BASE_URL" &&
    env_var_is CVR_TRACE_ENV prod; }; then
    az containerapp update --name "$AZURE_CONTAINER_APP" --resource-group "$AZURE_RESOURCE_GROUP" \
      --set-env-vars LANGFUSE_PUBLIC_KEY=secretref:langfuse-public-key \
      LANGFUSE_SECRET_KEY=secretref:langfuse-secret-key \
      "LANGFUSE_BASE_URL=$LANGFUSE_BASE_URL" CVR_TRACE_ENV=prod --output none
    wait_app_ready
  fi
  set_secret LANGFUSE_PUBLIC_KEY "$LANGFUSE_PUBLIC_KEY"
  set_secret LANGFUSE_SECRET_KEY "$LANGFUSE_SECRET_KEY"
  set_secret LANGFUSE_BASE_URL "$LANGFUSE_BASE_URL"
else
  warn "Langfuse skipped: the app runs untraced. Re-run this stage to add the keys."
fi
unset LANGFUSE_PUBLIC_KEY LANGFUSE_SECRET_KEY
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Smoke test the live app, then stop it"
say "Activates the latest revision, opens ingress and wakes the app from zero"
say "(scripts/demo.sh up), checks that /reformat refuses a request without the"
say "key, posts one golden-set document with it and checks for a .docx with"
say "X-Run-Id. Calls the model once (cents)."
say "Whatever happens, the app is stopped afterwards (scripts/demo.sh down: ingress"
say "closed, revision deactivated, no replica running): it is on for demos only."
if confirm "Run it?"; then
  if sh scripts/demo.sh up "$AZURE_RESOURCE_GROUP" "$AZURE_CONTAINER_APP"; then
    APP_URL="https://$(azq containerapp show --name "$AZURE_CONTAINER_APP" --resource-group "$AZURE_RESOURCE_GROUP" \
      --query properties.configuration.ingress.fqdn -o tsv)"
    write_env APP_URL "$APP_URL"
    note "URL: $APP_URL"
    sh scripts/smoke-deploy.sh "$APP_URL" || warn "the smoke test failed; see above"
  else
    warn "the app did not start; see above"
  fi
fi
unset CVR_API_KEY
if ! sh scripts/demo.sh down "$AZURE_RESOURCE_GROUP" "$AZURE_CONTAINER_APP"; then
  warn "the app may still be running: run sh scripts/demo.sh down, and check az containerapp replica list"
fi
say "Stopped. Start it for a demo with: sh scripts/demo.sh up"
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Entra app registration and the OIDC federated credential"
say "Creates $ENTRA_APP (the identity the deploy job signs in as), its service"
say "principal, Contributor on $AZURE_RESOURCE_GROUP only, and a federated"
say "credential trusting GitHub's tokens for exactly: $FED_SUBJECT"
confirm "Create them?" || { warn "stopped"; exit 1; }
AZURE_CLIENT_ID=$(azq ad app list --display-name "$ENTRA_APP" --query "[0].appId" -o tsv)
if [[ -z "$AZURE_CLIENT_ID" ]]; then
  AZURE_CLIENT_ID=$(azq ad app create --display-name "$ENTRA_APP" --query appId -o tsv)
fi
write_env AZURE_CLIENT_ID "$AZURE_CLIENT_ID"
az ad sp show --id "$AZURE_CLIENT_ID" >/dev/null 2>&1 || az ad sp create --id "$AZURE_CLIENT_ID" --output none
sp_object_id=$(azq ad sp show --id "$AZURE_CLIENT_ID" --query id -o tsv)
rg_id=$(azq group show --name "$AZURE_RESOURCE_GROUP" --query id -o tsv)
assigned=$(azq role assignment list --assignee "$sp_object_id" --scope "$rg_id" --role Contributor --query 'length(@)' -o tsv)
if [[ "$assigned" == 0 ]]; then
  az role assignment create --assignee-object-id "$sp_object_id" --assignee-principal-type ServicePrincipal \
    --role Contributor --scope "$rg_id" --output none
fi
# Create the credential, or bring an existing one's subject into line (an
# earlier run, or a hand edit, may have left a different one).
read -r cred_id cred_subject < <(azq ad app federated-credential list --id "$AZURE_CLIENT_ID" \
  --query "[?name=='github-main'].[id,subject] | [0]" -o tsv | tr '\t\n' '  ') || true
[[ "$cred_id" != None ]] || cred_id=
if [[ -n "$cred_id" && "$cred_subject" == "$FED_SUBJECT" ]]; then
  say "Credential github-main already trusts $FED_SUBJECT; leaving it."
else
  if [[ -n "$cred_id" ]]; then
    warn "github-main trusts '$cred_subject', not '$FED_SUBJECT'; updating it."
  fi
  cred=$(mktemp)
  cat > "$cred" <<JSON
{
  "name": "github-main",
  "issuer": "https://token.actions.githubusercontent.com",
  "subject": "$FED_SUBJECT",
  "description": "GitHub Actions deploy job, push to main only",
  "audiences": ["api://AzureADTokenExchange"]
}
JSON
  if [[ -n "$cred_id" ]]; then
    az ad app federated-credential update --id "$AZURE_CLIENT_ID" --federated-credential-id "$cred_id" \
      --parameters "$(winpath "$cred")" --output none
  else
    az ad app federated-credential create --id "$AZURE_CLIENT_ID" --parameters "$(winpath "$cred")" --output none
  fi
  rm -f "$cred"
fi
az ad app federated-credential list --id "$AZURE_CLIENT_ID" --query "[].{name:name, subject:subject}" --output table
say "Client id: $AZURE_CLIENT_ID. No client secret was created."
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "GitHub repository secrets and variables"
say "The deploy job logs in with the three ids. They are identifiers, not"
say "credentials (without a token from this repo's main branch they open"
say "nothing), but azure/login echoes its inputs, so they are secrets: GitHub"
say "masks secrets in the log. The two resource names stay variables."
set_secret AZURE_CLIENT_ID "$AZURE_CLIENT_ID"
set_secret AZURE_TENANT_ID "$AZURE_TENANT_ID"
set_secret AZURE_SUBSCRIPTION_ID "$AZURE_SUBSCRIPTION_ID"
set_var AZURE_RESOURCE_GROUP "$AZURE_RESOURCE_GROUP"
set_var AZURE_CONTAINER_APP "$AZURE_CONTAINER_APP"
say "The repository's secrets (expect ANTHROPIC_API_KEY, CVR_API_KEY, LANGFUSE_PUBLIC_KEY,"
say "LANGFUSE_SECRET_KEY, LANGFUSE_BASE_URL and the"
say "three AZURE ids; no Azure credential, since the deploy signs in through OIDC):"
gh secret list
pause

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Cost budget"
say "The target is the free monthly grant. A budget alert is the tripwire; if it"
say "ever fires, kill whatever costs money: az group delete -n $AZURE_RESOURCE_GROUP"
open_url "https://portal.azure.com/#view/Microsoft_Azure_CostManagement/Menu/~/budgets"
step "If the link lands elsewhere: search the portal for 'Budgets' → Cost Management | Budgets."
step "Scope: your subscription. + Add → name cvr-budget, reset Monthly, amount e.g. 5."
step "Alert conditions: Actual 50% and 100%, Forecasted 100%; your email → Create."
ask_default BUDGET_AMOUNT "Monthly amount you set (subscription currency)" 5
pause

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Log retention: the ContainerApp tables Azure lets us change keep 4 days"
say "$LOG_WORKSPACE stays at 30 days, the least PerGB2018 allows for the workspace."
say "Each ContainerApp table (system, console, HTTP logs and their _CL variants) is"
say "set to 4 days of retention and 4 in total, the per-table minimum. The two classic"
say "_CL tables, the only ones the app writes to, refuse that (the table API needs a"
say "one-way migration): they are warned about and keep the workspace 30 days; the"
say "others are empty. The logs of"
say "a request are kept no longer than a few days. The first 31 days cost nothing"
say "extra: this is about keeping data less long, not about cost. Reads each table"
say "first and updates only one that differs, so a re-run changes nothing."
note "A table appears after the app's first logs; one that does not exist yet is"
note "skipped, and a later re-run of this stage picks it up."
LOG_TABLE_RETENTION_DAYS=4
mapfile -t log_tables < <(azq monitor log-analytics workspace table list --resource-group "$AZURE_RESOURCE_GROUP"   --workspace-name "$LOG_WORKSPACE" --query "[?starts_with(name, 'ContainerApp')].name" -o tsv)
if [[ "${#log_tables[@]}" == 0 ]]; then
  warn "no ContainerApp table exists in $LOG_WORKSPACE yet; run the smoke test (stage 8), wait a few minutes and re-run this stage."
fi
for table in "${log_tables[@]}"; do
  [[ -n "$table" ]] || continue
  current=$(azq monitor log-analytics workspace table show --resource-group "$AZURE_RESOURCE_GROUP"     --workspace-name "$LOG_WORKSPACE" --name "$table" --query "[retentionInDays, totalRetentionInDays]" -o tsv | tr '	
' '  ')
  current=${current% }
  wanted="$LOG_TABLE_RETENTION_DAYS $LOG_TABLE_RETENTION_DAYS"
  if [[ "$current" != "$wanted" ]]; then
    note "$table: retention and total were '$current'; setting $wanted."
    if ! err=$(az monitor log-analytics workspace table update --resource-group "$AZURE_RESOURCE_GROUP"       --workspace-name "$LOG_WORKSPACE" --name "$table"       --retention-time "$LOG_TABLE_RETENTION_DAYS" --total-retention-time "$LOG_TABLE_RETENTION_DAYS" --output none 2>&1); then
      # A classic custom table (the _CL ones) refuses the table API until it is migrated, and
      # migrating cannot be undone, so it is left alone: warn and go on (stage 13 still runs).
      warn "$table: could not set retention, left at '$current' ($(printf '%s' "$err" | head -n 1))"
      continue
    fi
  else
    note "$table: already $wanted; leaving it."
  fi
  # Read back: the value recorded on ticket 06 for ADR-0013.
  say "$table: $(azq monitor log-analytics workspace table show --resource-group "$AZURE_RESOURCE_GROUP"     --workspace-name "$LOG_WORKSPACE" --name "$table" --query "[retentionInDays, totalRetentionInDays]" -o tsv | tr '	
' '  ')(retention, total, days)"
done
pause

# ── 13 ────────────────────────────────────────────────────────────────────
# Phase 2 ticket 18: the Azure OpenAI path, with no key anywhere. An Azure AI
# Services (Foundry) account with a custom subdomain and local (key) auth
# disabled, a Data Zone Standard deployment, and the role Cognitive
# Services OpenAI User on the account alone for cvr-ca's managed identity and
# for the maintainer. The app's env is not touched here (ticket 19 switches it).
# The account has its own region (2026-10-24: cvr_sub has no gpt-5.4 quota in
# northeurope or anywhere in the EU; gpt-5.4-mini has 200K TPM in swedencentral,
# westeurope, germanywestcentral and francecentral), and its own model choice,
# remembered: gpt-5.4-mini by default, gpt-5.6-terra (its quota request was
# refused 2026-10-29 for region capacity) or gpt-5.4 if quota ever appears. Each model
# is its own deployment, named after the model; re-running with the other model
# adds that deployment and leaves the first alone.
stage "Azure OpenAI: account, deployment and roles (no keys)"
AOAI_SKU=DataZoneStandard
AOAI_ROLE="Cognitive Services OpenAI User"
# model_version MODEL: the version the deployment pins (Microsoft Learn, models
# sold directly by Azure); model_default_capacity MODEL: thousands of TPM.
model_version() {
  case "$1" in
    gpt-5.4) printf '2026-03-05' ;;
    gpt-5.4-mini) printf '2026-03-17' ;;
    gpt-5.6-terra) printf '2026-07-09' ;;
    *) return 1 ;;
  esac
}
model_default_capacity() {
  case "$1" in
    gpt-5.4) printf '500' ;;
    gpt-5.4-mini) printf '200' ;;
    gpt-5.6-terra) printf '200' ;;
    *) return 1 ;;
  esac
}
ask_default AZURE_OPENAI_LOCATION "Region of the Azure OpenAI account (the app stays in $AZURE_LOCATION)" swedencentral
# Validated before it is remembered, so a typo is never written to .env.azure.
ask AZURE_OPENAI_MODEL "Model to deploy (gpt-5.4-mini, gpt-5.6-terra or gpt-5.4) [gpt-5.4-mini]"
[[ -n "$AZURE_OPENAI_MODEL" ]] || AZURE_OPENAI_MODEL=gpt-5.4-mini
AOAI_MODEL=$AZURE_OPENAI_MODEL
AOAI_MODEL_VERSION=$(model_version "$AOAI_MODEL") \
  || { warn "AZURE_OPENAI_MODEL must be gpt-5.4-mini, gpt-5.6-terra or gpt-5.4, not '$AOAI_MODEL'; nothing was remembered"; exit 1; }
write_env AZURE_OPENAI_MODEL "$AOAI_MODEL"
AOAI_USAGE_NAME="OpenAI.$AOAI_SKU.$AOAI_MODEL"
# The deployment is named after its model, so the two never disagree.
AZURE_OPENAI_DEPLOYMENT=$AOAI_MODEL
say "Creates (or confirms) an AIServices account in $AZURE_RESOURCE_GROUP ($AZURE_OPENAI_LOCATION) with local"
say "(key) authentication disabled, a $AOAI_SKU $AOAI_MODEL $AOAI_MODEL_VERSION deployment, and the role"
say "'$AOAI_ROLE' on that account only, for $AZURE_CONTAINER_APP's"
say "system-assigned identity and for you. No key is created, listed or stored."
note "Role assignments need Owner or User Access Administrator on the account's scope."
say "Registering Microsoft.CognitiveServices if needed (never used on this subscription before)."
if [[ "$(azq provider show --namespace Microsoft.CognitiveServices --query registrationState -o tsv)" != Registered ]]; then
  az provider register --namespace Microsoft.CognitiveServices --wait
fi
for _ in $(seq 60); do
  [[ "$(azq provider show --namespace Microsoft.CognitiveServices --query registrationState -o tsv)" == Registered ]] && break
  sleep 5
done
[[ "$(azq provider show --namespace Microsoft.CognitiveServices --query registrationState -o tsv)" == Registered ]] \
  || { warn "Microsoft.CognitiveServices is still not Registered; see az provider show"; exit 1; }
say "Reading the $AOAI_SKU quota for $AOAI_MODEL in $AZURE_OPENAI_LOCATION (the row $AOAI_USAGE_NAME)."
quota_limit=$(azq cognitiveservices usage list --location "$AZURE_OPENAI_LOCATION" \
  --query "[?name.value=='$AOAI_USAGE_NAME'].limit | [0]" -o tsv)
quota_used=$(azq cognitiveservices usage list --location "$AZURE_OPENAI_LOCATION" \
  --query "[?name.value=='$AOAI_USAGE_NAME'].currentValue | [0]" -o tsv)
# The CLI may print 500.0; capacity units are whole thousands of tokens a minute.
quota_limit=${quota_limit%%.*}
quota_used=${quota_used%%.*}
if [[ -z "$quota_limit" || "$quota_limit" == None || "$quota_limit" == 0 ]]; then
  warn "No $AOAI_SKU quota for $AOAI_MODEL in $AZURE_OPENAI_LOCATION (limit '${quota_limit:-absent}'). Nothing was created."
  say "Every gpt-5.4 row the subscription reports (an empty table means the row is named differently or absent):"
  az cognitiveservices usage list -l "$AZURE_OPENAI_LOCATION"     --query "[?contains(name.value,'gpt-5.4')].{name:name.value,limit:limit,used:currentValue}" -o table || true
  say "Either request quota in the portal (Foundry > Quotas > $AOAI_MODEL, $AOAI_SKU, $AZURE_OPENAI_LOCATION), pick"
  say "another region or model (AZURE_OPENAI_LOCATION, AZURE_OPENAI_MODEL in .env.azure) and re-run this wizard,"
  say "or record the Azure path as blocked (tickets 18-21)."
  exit 1
fi
quota_free=$((quota_limit - ${quota_used:-0}))
say "Quota: limit $quota_limit, used ${quota_used:-0}, available $quota_free (thousands of tokens a minute)."
capacity_cap=$(model_default_capacity "$AOAI_MODEL")
if (( quota_free > capacity_cap )); then capacity_default=$capacity_cap; else capacity_default=$quota_free; fi
step "Azure counts max_completion_tokens (32000 in our Azure requests) against the TPM limit of"
step "every call, so labellings in flight need capacity: with 200 run the eval at --concurrency 2."
# A remembered capacity belongs to its model: AZURE_OPENAI_CAPACITY_GPT_5_4_MINI.
capacity_key="AZURE_OPENAI_CAPACITY_$(printf '%s' "$AOAI_MODEL" | tr 'a-z.-' 'A-Z__')"
ask_default "$capacity_key" "Capacity in thousands of TPM (available $quota_free)" "$capacity_default"
AZURE_OPENAI_CAPACITY=${!capacity_key}
[[ "$AZURE_OPENAI_CAPACITY" =~ ^[0-9]+$ && "$AZURE_OPENAI_CAPACITY" -ge 1 ]] \
  || { warn "capacity must be a whole number of at least 1"; exit 1; }
ask_default AZURE_OPENAI_ACCOUNT "Account name (its subdomain is globally unique)" "cvr-aoai-$(openssl rand -hex 2)"
confirm "Create or confirm them?" || { warn "stopped before creating anything"; exit 1; }

# The account: AIServices (Foundry), S0, with a custom subdomain, which token
# authentication requires.
if az cognitiveservices account show --name "$AZURE_OPENAI_ACCOUNT" --resource-group "$AZURE_RESOURCE_GROUP" >/dev/null 2>&1; then
  [[ "$(azq cognitiveservices account show --name "$AZURE_OPENAI_ACCOUNT" --resource-group "$AZURE_RESOURCE_GROUP"     --query kind -o tsv)" == AIServices ]]     || { warn "$AZURE_OPENAI_ACCOUNT exists but is not kind AIServices; pick another name or delete it"; exit 1; }
  # The quota was read for AZURE_OPENAI_LOCATION, and an account cannot move.
  [[ "$(azq cognitiveservices account show --name "$AZURE_OPENAI_ACCOUNT" --resource-group "$AZURE_RESOURCE_GROUP"     --query location -o tsv)" == "$AZURE_OPENAI_LOCATION" ]]     || { warn "$AZURE_OPENAI_ACCOUNT exists in another region than $AZURE_OPENAI_LOCATION; set AZURE_OPENAI_LOCATION to its region or pick another account name"; exit 1; }
  say "Account $AZURE_OPENAI_ACCOUNT already exists; keeping it."
else
  az cognitiveservices account create --name "$AZURE_OPENAI_ACCOUNT" --resource-group "$AZURE_RESOURCE_GROUP" \
    --location "$AZURE_OPENAI_LOCATION" --kind AIServices --sku S0 --custom-domain "$AZURE_OPENAI_ACCOUNT" \
    --yes --output none
  say "Created account $AZURE_OPENAI_ACCOUNT."
fi
aoai_id=$(azq cognitiveservices account show --name "$AZURE_OPENAI_ACCOUNT" --resource-group "$AZURE_RESOURCE_GROUP" \
  --query id -o tsv)
[[ "$(azq cognitiveservices account show --name "$AZURE_OPENAI_ACCOUNT" --resource-group "$AZURE_RESOURCE_GROUP" \
  --query properties.customSubDomainName -o tsv)" == "$AZURE_OPENAI_ACCOUNT" ]] \
  || { warn "$AZURE_OPENAI_ACCOUNT has no custom subdomain of that name; token authentication needs it"; exit 1; }

# Key authentication off: az cognitiveservices has no flag, so ARM, only when
# it is not already off.
if [[ "$(azq cognitiveservices account show --name "$AZURE_OPENAI_ACCOUNT" --resource-group "$AZURE_RESOURCE_GROUP" \
  --query properties.disableLocalAuth -o tsv)" == true ]]; then
  say "Local (key) authentication is already disabled."
else
  # Right after the account is created ARM may still be provisioning it and
  # answer with a conflict; try a few times.
  disabled=0
  for _ in 1 2 3 4 5 6; do
    if az resource update --ids "$aoai_id" --api-version 2024-10-01       --set properties.disableLocalAuth=true --output none; then disabled=1; break; fi
    note "the account may still be provisioning; retrying in 10 seconds"
    sleep 10
  done
  [[ "$disabled" == 1 ]] || { warn "could not disable local authentication; see the error above"; exit 1; }
  say "Disabled local (key) authentication."
fi

# The deployment.
if az cognitiveservices account deployment show --name "$AZURE_OPENAI_ACCOUNT" --resource-group "$AZURE_RESOURCE_GROUP" \
  --deployment-name "$AZURE_OPENAI_DEPLOYMENT" >/dev/null 2>&1; then
  say "Deployment $AZURE_OPENAI_DEPLOYMENT already exists; keeping it."
else
  if (( AZURE_OPENAI_CAPACITY > quota_free )); then
    warn "capacity $AZURE_OPENAI_CAPACITY is above the $quota_free available; re-run with less"
    exit 1
  fi
  az cognitiveservices account deployment create --name "$AZURE_OPENAI_ACCOUNT" --resource-group "$AZURE_RESOURCE_GROUP" \
    --deployment-name "$AZURE_OPENAI_DEPLOYMENT" --model-format OpenAI --model-name "$AOAI_MODEL" \
    --model-version "$AOAI_MODEL_VERSION" --sku-name "$AOAI_SKU" --sku-capacity "$AZURE_OPENAI_CAPACITY" --output none
  say "Created deployment $AZURE_OPENAI_DEPLOYMENT."
fi

# Roles: the app's system-assigned identity and the signed-in maintainer, each
# the inference role on the account (not the resource group).
app_principal=$(azq containerapp identity show --name "$AZURE_CONTAINER_APP" --resource-group "$AZURE_RESOURCE_GROUP" \
  --query principalId -o tsv 2>/dev/null || true)
if [[ -z "$app_principal" || "$app_principal" == None ]]; then
  az containerapp identity assign --name "$AZURE_CONTAINER_APP" --resource-group "$AZURE_RESOURCE_GROUP" \
    --system-assigned --output none
  wait_app_ready
  app_principal=$(azq containerapp identity show --name "$AZURE_CONTAINER_APP" --resource-group "$AZURE_RESOURCE_GROUP" \
    --query principalId -o tsv)
  say "Enabled the system-assigned identity on $AZURE_CONTAINER_APP."
else
  say "$AZURE_CONTAINER_APP already has a system-assigned identity."
fi
user_principal=$(azq ad signed-in-user show --query id -o tsv)   || { warn "az ad signed-in-user show failed: grant '$AOAI_ROLE' on $AZURE_OPENAI_ACCOUNT to yourself by hand, then re-run"; exit 1; }
grant_role() {
  local who="$1" type="$2" label="$3" have
  have=$(azq role assignment list --assignee-object-id "$who" --fill-principal-name false --scope "$aoai_id" --role "$AOAI_ROLE" --query 'length(@)' -o tsv)
  if [[ "$have" == 0 ]]; then
    az role assignment create --assignee-object-id "$who" --assignee-principal-type "$type" \
      --role "$AOAI_ROLE" --scope "$aoai_id" --output none
    say "Granted '$AOAI_ROLE' on $AZURE_OPENAI_ACCOUNT to $label."
  else
    say "$label already holds '$AOAI_ROLE' on $AZURE_OPENAI_ACCOUNT."
  fi
}
grant_role "$app_principal" ServicePrincipal "$AZURE_CONTAINER_APP's identity"
grant_role "$user_principal" User "you"

# Read back, and fail loudly on anything unexpected.
say "Read-back:"
local_auth_off=$(azq cognitiveservices account show --name "$AZURE_OPENAI_ACCOUNT" --resource-group "$AZURE_RESOURCE_GROUP" \
  --query properties.disableLocalAuth -o tsv)
subdomain=$(azq cognitiveservices account show --name "$AZURE_OPENAI_ACCOUNT" --resource-group "$AZURE_RESOURCE_GROUP" \
  --query properties.customSubDomainName -o tsv)
deployments=$(azq cognitiveservices account deployment list --name "$AZURE_OPENAI_ACCOUNT" \
  --resource-group "$AZURE_RESOURCE_GROUP" --query "[].name" -o tsv)
note "  disableLocalAuth  $local_auth_off"
note "  subdomain         $subdomain"
note "  location          $(azq cognitiveservices account show --name "$AZURE_OPENAI_ACCOUNT" --resource-group "$AZURE_RESOURCE_GROUP" --query location -o tsv)"
bad=0
# Every deployment on the account, not only the one just made: each must be
# Data Zone Standard at the version pinned for its model.
chosen_found=0
while IFS= read -r dep; do
  [[ -n "$dep" ]] || continue
  dep_info=$(azq cognitiveservices account deployment show --name "$AZURE_OPENAI_ACCOUNT" \
    --resource-group "$AZURE_RESOURCE_GROUP" --deployment-name "$dep" \
    --query "[sku.name, sku.capacity, properties.model.name, properties.model.version]" -o tsv | tr '\t\n' '  ')
  read -r dep_sku dep_capacity dep_model dep_version <<<"$dep_info"
  note "  deployment        $dep: $dep_model $dep_version, sku $dep_sku, capacity $dep_capacity"
  [[ "$dep" != "$AZURE_OPENAI_DEPLOYMENT" ]] || chosen_found=1
  [[ "$dep_sku" == "$AOAI_SKU" ]] || { warn "deployment $dep sku is '$dep_sku', not $AOAI_SKU"; bad=1; }
  want_version=$(model_version "$dep_model" || true)
  [[ -n "$want_version" && "$dep_version" == "$want_version" ]] \
    || { warn "deployment $dep: model '$dep_model' version '$dep_version' is not a pinned pair"; bad=1; }
done <<<"$deployments"
[[ "$chosen_found" == 1 ]] || { warn "deployment $AZURE_OPENAI_DEPLOYMENT is not on the account"; bad=1; }
az role assignment list --scope "$aoai_id" --fill-principal-name false   --query "[].{principal:principalId, type:principalType, role:roleDefinitionName}" --output table || true
[[ "$local_auth_off" == true ]] || { warn "local authentication is NOT disabled"; bad=1; }
for who in "$app_principal" "$user_principal"; do
  [[ "$(azq role assignment list --assignee-object-id "$who" --fill-principal-name false --scope "$aoai_id" --query 'length(@)' -o tsv)" == 1 \
    && "$(azq role assignment list --assignee-object-id "$who" --fill-principal-name false --scope "$aoai_id" --role "$AOAI_ROLE" --query 'length(@)' -o tsv)" == 1 ]] \
    || { warn "a principal does not hold exactly '$AOAI_ROLE' on the account"; bad=1; }
done
(( bad == 0 )) || { warn "the read-back found a problem; fix it and re-run this stage"; exit 1; }
AZURE_OPENAI_ENDPOINT="https://$subdomain.openai.azure.com/"
write_env AZURE_OPENAI_ENDPOINT "$AZURE_OPENAI_ENDPOINT"
write_env AZURE_OPENAI_DEPLOYMENT "$AZURE_OPENAI_DEPLOYMENT"
say "Read-back is as wanted. The app will need (ticket 19 sets them; nothing was changed here):"
note "  CVR_LABEL_PROVIDER=azure_openai"
note "  CVR_LABEL_AZURE_ENDPOINT=$AZURE_OPENAI_ENDPOINT"
note "  CVR_LABEL_AZURE_DEPLOYMENT=$AZURE_OPENAI_DEPLOYMENT"
note "Role changes can take up to five minutes to take effect."
# Insurance: the identity change makes a revision; the app must stay off.
running_now=$(azq containerapp replica list --name "$AZURE_CONTAINER_APP" --resource-group "$AZURE_RESOURCE_GROUP"   --revision "$(azq containerapp show --name "$AZURE_CONTAINER_APP" --resource-group "$AZURE_RESOURCE_GROUP"     --query properties.latestRevisionName -o tsv)"   --query "[?properties.runningState=='Running'] | length(@)" -o tsv 2>/dev/null || echo "?")
if [[ "$running_now" != 0 ]]; then
  warn "$AZURE_CONTAINER_APP may have $running_now replica(s) running: run sh scripts/demo.sh down and check az containerapp replica list"
fi
pause

# ── 14 ────────────────────────────────────────────────────────────────────
stage "Record for ADR-0010"
say "Paste this into the ticket 14 PR and check ADR-0010's table matches:"
printf '\n'
note "  subscription      $AZURE_SUBSCRIPTION_ID"
note "  tenant            $AZURE_TENANT_ID"
note "  region            $AZURE_LOCATION"
note "  resource group    $AZURE_RESOURCE_GROUP"
note "  log analytics     $LOG_WORKSPACE ($LOG_WORKSPACE_ID)"
note "  environment       $CONTAINERAPPS_ENV"
note "  container app     $AZURE_CONTAINER_APP  $APP_URL"
note "  image             $IMAGE (public)"
note "  entra app         $ENTRA_APP (client id $AZURE_CLIENT_ID)"
note "  oidc subject      $FED_SUBJECT"
note "  budget            $BUDGET_AMOUNT a month"
note "  log retention     workspace 30 days; the populated _CL tables 30 days; the other ContainerApp tables ${LOG_TABLE_RETENTION_DAYS:-4} days (stage 12)"
note "  azure openai      ${AZURE_OPENAI_ACCOUNT:-not provisioned} in ${AZURE_OPENAI_LOCATION:-n/a} / ${AZURE_OPENAI_DEPLOYMENT:-}, no keys (stage 13)"
printf '\n'
say "Next: merge to main; the deploy job moves the app from :bootstrap to the commit's image."
pause "Press Enter to finish"

finish
